// Check scan timing for qmd_index_incremental
const qmdIndexJob = cron.jobs.find(function(j) { return j.name === 'qmd_index_incremental'; });
const lastQmdScan = new Date(qmdIndexJob.lastRunTimestamp).getTime();
const sinceLastScan = now - lastQmdScan;
const maxInterval = qmdIndexJob.intervalMinutes * 60 * 1000;

// Check if scan was within allowed interval
const scanTimely = sinceLastScan <= maxInterval;

// Count project breakdown
const projectBreakdown = {};
index.files.forEach(function(file) {
  const projectPath = file.path;
  let projectName = projectPath.split('/').find(function(p) { return p.includes('/projects/'); });
  if (!projectName) {
    projectName = 'Unknown';
  } else {
    projectName = projectPath.split('/').slice(projectPath.indexOf('/projects/') + 1).join('/');
  }
  if (!projectBreakdown[projectName]) {
    projectBreakdown[projectName] = 0;
  }
  projectBreakdown[projectName]++;
});

console.log('\n=== INDEX AUDIT RESULTS ===\n');
console.log('Total files indexed:', index.totalFiles);
console.log('Generated at:', index.generatedAt);
console.log('Scan last ran:', new Date(qmdIndexJob.lastRunTimestamp).toLocaleString());
console.log('Last scan was', Math.floor(sinceLastScan / 60000), 'minutes ago');
console.log('Max allowed interval:', qmdIndexJob.intervalMinutes, 'minutes');
console.log('Was timely:', scanTimely ? 'YES' : 'NO');

console.log('\nOutdated files:');
const staleFiles = findings.filter(function(f) { return f.issue_type === 'file_stale'; });
