};

fs.writeFileSync('reports/audit-findings.json', JSON.stringify(findingsJSON, null, 2));

// Create markdown audit report
var report = '# QMD File Index Audit Report\n\n';
report = report + '**Generated:** ' + currentDateTime;
report = report + '\n\n';
report = report + '**Index Created:** ' + index.generatedAt;
report = report + '\n\n';
report = report + '## Summary\n\n';
report = report + '| Metric | Value |';
report = report + '\n|--------|-------|';
report = report + '\n| Total Indexed Files | ' + index.totalFiles + ' |';
report = report + '\n| Issues Found | ' + findings.length + ' |';
report = report + '\n| Stale Files | ' + findings.filter(function(f) { return f.issue_type === 'file_stale'; }).length + ' |';
report = report + '\n| Missed Scans | ' + findings.filter(function(f) { return f.issue_type === 'scan_delayed'; }).length + ' |';
report = report + '\n\n';
report = report + '## Files Indexed by Project\n\n';
report = report + '| Project | Files | Percentage |';
report = report + '\n|---------|-------|------------|';
Object.keys(projectBreakdown).forEach(function(p) {
  const pct = ((projectBreakdown[p] / index.totalFiles) * 100).toFixed(1);
  report = report + '\n| ' + p + ' | ' + projectBreakdown[p] + ' | ' + pct + '% |';
});
report = report + '\n\n';
report = report + '## Scheduled Scan Status\n\n';
report = report + '| Job Name | Last Run | Interval | Status |';
report = report + '\n|----------|----------|----------|--------|';
cron.jobs.forEach(function(job) {
  const minutesAgo = Math.floor((now - new Date(job.lastRunTimestamp).getTime()) / 60000);
  const status = minutesAgo <= job.intervalMinutes ? 'OK - On Schedule' : 'WARNING - Overdue by ' + (minutesAgo - job.intervalMinutes) + ' min';
  report = report + '\n| ' + job.name + ' | ' + new Date(job.lastRunTimestamp).toLocaleString() + ' | ' + job.intervalMinutes + ' min | ' + status + ' |';
});
report = report + '\n\n';
report = report + '## Outdated Files\n\n';
report = report + 'Files that have been modified since the last scan:\n\n';
if (findings.length === 0) {
  report = report + '- None detected\n\n';
} else {
  findings.forEach(function(f) {
    report = report + '- **' + f.evidence_file.split('/').pop() + '** (' + f.issue_type + '): ' + f.finding + '\n\n';
    report = report + 'Recommendation: ' + f.recommendation + '\n\n';
  });
}
report = report + '\n## Root Cause Analysis\n\n';
if (findings.length === 0) {
  report = report + 'The index is current. All files have been indexed within acceptable time thresholds, and scheduled scans are running on time. No action required.\n\n';
} else {
  const scanIssues = findings.filter(function(f) { return f.issue_type === 'scan_delayed'; });
  const fileIssues = findings.filter(function(f) { return f.issue_type === 'file_stale'; });

  if (scanIssues.length > 0 && fileIssues.length > 0) {
    report = report + 'The primary issue is that scheduled scans are NOT running on schedule. This has caused ' + fileIssues.length + ' files to remain stale (not yet indexed).\n\n';
    report = report + '**Recommended Action:** Manually trigger an incremental index update immediately, then investigate the scheduling mechanism (crontab/systemd timer).\n\n';
  } else if (fileIssues.length > 0) {
    report = report + fileIssues.length + ' files have been modified since the last scan, but the scans may have been delayed. Check the scheduler status.\n\n';
  } else if (scanIssues.length > 0) {
    report = report + scanIssues.length + ' scheduled jobs are overdue. Check crontab or scheduler service status.\n\n';
  } else {
    report = report + 'No issues detected.\n\n';
  }
}

fs.writeFileSync('reports/index-audit.md', report);

